// Helper functions
export const getFoodById = (id) => FOOD_DATABASE.find((f) => f.id === id);
export const searchFoods = (query) => {
  const q = query.toLowerCase();
  return FOOD_DATABASE.filter((f) => f.name.toLowerCase().includes(q));
};
export const getCategories = () => [...new Set(FOOD_DATABASE.map((f) => f.category))];